lesson('generators', [
 ('yield', [['title','yield'],['code','def drops():'],['code','    yield 1'],['code','    yield 2']],
  "A generator is a function that uses yield instead of return. def drops. yield one. yield two.",
  ['A generator is a function','def drops','yield one','yield two']),
 ('Pause', [['title','A generator pauses'],['code','g = drops()'],['code','next(g)'],['out','→ 1'],['code','next(g)'],['out','→ 2']],
  "Calling drops does not run it yet. g equals drops. next of g runs up to the first yield and gives one, then pauses. next again carries on to the next yield: two.",
  ['Calling drops does not run it','g equals drops','next of g runs up to','gives one','next again carries on','two']),
 ('Loop', [['title','Loops with yield'],['code','def rain(days):'],['code','    for litres in days:'],['code','        if litres > 0:'],['code','            yield litres']],
  "Put yield in a loop. def rain, days. for litres in days: if litres is more than zero, yield litres. Dry days are skipped.",
  ['Put yield in a loop','def rain, days','for litres in days','if litres is more than zero','yield litres']),
 ('Expression', [['title','Generator expressions'],['code','squares = (n * n for n in range(5))'],['code','sum(squares)'],['out','→ 30']],
  "A comprehension in round brackets is a generator expression. squares equals n times n for n in range five. sum of squares is thirty, and no list was ever made.",
  ['A comprehension in round brackets','squares equals','sum of squares','is thirty']),
 ('Endless', [['title','Endless, safely'],['code','def days():'],['code','    n = 1'],['code','    while True:'],['code','        yield n; n += 1']],
  "A generator can go on forever, because it only makes the next value when asked. def days. n equals one. while True: yield n, then add one.",
  ['A generator can go on forever','def days','n equals one','while True','yield n']),
 ('Pipeline', [['title','Pipelines'],['code','lines = open("log.txt")'],['code','wet = (l for l in lines if "rain" in l)'],['code','print(next(wet))']],
  "Generators can feed each other, like pipes. lines equals open log dot t x t. wet equals each l in lines if rain is in l. print next of wet reads just enough lines to find the first rainy one.",
  ['Generators can feed each other','lines equals open','wet equals','print next of wet']),
 ('yield from', [['title','yield from'],['code','def all_rain():'],['code','    yield from roof()'],['code','    yield from shed()']],
  "yield from hands over to another generator. def all rain. yield from roof, then yield from shed: every drop from both, one at a time.",
  ['yield from hands over','def all rain','yield from roof','then yield from shed']),
 ('When', [['title','When to use one'],['chalk','huge data, one item at a time'],['chalk','streams that never end'],['chalk','a list when you need it all at once']],
  "Use a generator for huge data, one item at a time, or for streams that never end. Use a list when you need everything at once, or need to go through it twice.",
  ['Use a generator','for huge data','streams that never end','Use a list when']),
])
